import { Buffer } from "buffer";
import { createHash, KeyObject, verify } from "crypto";
import {
  BFTSigningInterface,
  BFTVerificationInterface,
} from "./BFTConsensusCoordinator";

/**
 * Domain separator for cryptographic view-change timeout challenges.
 */
export const TIMEOUT_CHALLENGE_DOMAIN = "BFT_TIMEOUT_CHALLENGE_V1";
export const TIMEOUT_WITNESS_DOMAIN = "BFT_TIMEOUT_WITNESS_V1";

/**
 * Challenge generated by a validator requesting a view change due to a timeout.
 */
export interface ViewChangeTimeoutChallenge {
  challengeId: string;
  view: number;
  newView: number;
  sequence: number;
  proposerId: string;
  timeoutDurationMs: number;
  createdAt: number;
  /** Signature by the challenger (proposerId) over the canonical challenge payload */
  challengerSignature: string;
}

/**
 * Cryptographic witness signature from a validator certifying the elapsed timeout.
 */
export interface TimeoutWitnessProof {
  witnessNodeId: string;
  witnessTimestamp: number;
  signature: string;
}

/**
 * Complete timeout evidence packaging the challenge and validator witness signatures.
 */
export interface CryptographicTimeoutEvidence {
  challenge: ViewChangeTimeoutChallenge;
  witnesses: TimeoutWitnessProof[];
}

/**
 * Canonical challenge payload options.
 */
export interface ChallengePayloadParams {
  challengeId: string;
  view: number;
  newView: number;
  sequence: number;
  proposerId: string;
  timeoutDurationMs: number;
  createdAt: number;
}

/**
 * Format the canonical domain-separated payload for a timeout challenge.
 */
export function formatChallengePayload(
  params: ChallengePayloadParams,
): Uint8Array {
  return Buffer.from(
    `${TIMEOUT_CHALLENGE_DOMAIN}:${params.challengeId}:${params.view}:${params.newView}:${params.sequence}:${params.proposerId}:${params.timeoutDurationMs}:${params.createdAt}`,
    "utf8",
  );
}

/**
 * Format the canonical domain-separated payload for a witness timestamp signature.
 */
export function formatWitnessPayload(
  challengeId: string,
  witnessNodeId: string,
  witnessTimestamp: number,
): Uint8Array {
  return Buffer.from(
    `${TIMEOUT_WITNESS_DOMAIN}:${challengeId}:${witnessNodeId}:${witnessTimestamp}`,
    "utf8",
  );
}

/**
 * Verification options for timeout challenge and witness proofs.
 */
export interface TimeoutVerificationContext {
  currentView: number;
  currentSequence: number;
  expectedTimeoutMs: number;
  validators: string[];
  quorumSize: number;
  validatorPublicKeys?: Map<string, KeyObject>;
  verifier?: BFTVerificationInterface;
  /** Allowed clock tolerance between validators in ms (default: 10,000ms) */
  clockToleranceMs?: number;
  /** Current wall-clock time for verification */
  now?: number;
}

/**
 * State tracking and challenge generation for view changes.
 */
export class ViewChangeManager {
  private usedChallengeIds: Set<string> = new Set();
  private pendingChallenges: Map<string, ViewChangeTimeoutChallenge> =
    new Map();
  private challengeWitnesses: Map<string, Map<string, TimeoutWitnessProof>> =
    new Map();
  // Bound active challenges by view: view -> Set<challengeId>
  private challengesByView: Map<number, Set<string>> = new Map();

  constructor(
    private readonly maxTrackedChallenges: number = 1000,
    private readonly clockToleranceMs: number = 10000,
  ) {}

  /**
   * Generates a deterministic or random unique challenge identifier.
   */
  public generateChallengeId(
    view: number,
    newView: number,
    sequence: number,
    nodeId: string,
    timestamp: number,
  ): string {
    const raw = `${view}:${newView}:${sequence}:${nodeId}:${timestamp}:${Math.random().toString(36).slice(2)}`;
    return createHash("sha256").update(raw).digest("hex");
  }

  /**
   * Creates and cryptographically signs a new timeout challenge.
   */
  public createTimeoutChallenge(
    view: number,
    newView: number,
    sequence: number,
    proposerId: string,
    timeoutDurationMs: number,
    signer: BFTSigningInterface,
    now: number = Date.now(),
  ): ViewChangeTimeoutChallenge {
    if (newView <= view) {
      throw new Error(
        `Invalid newView ${newView}: must be greater than current view ${view}`,
      );
    }
    if (timeoutDurationMs <= 0) {
      throw new Error(
        `Invalid timeoutDurationMs ${timeoutDurationMs}: must be positive`,
      );
    }

    const challengeId = this.generateChallengeId(
      view,
      newView,
      sequence,
      proposerId,
      now,
    );
    const payload = formatChallengePayload({
      challengeId,
      view,
      newView,
      sequence,
      proposerId,
      timeoutDurationMs,
      createdAt: now,
    });

    const challengerSignature = signer.sign(payload);

    const challenge: ViewChangeTimeoutChallenge = {
      challengeId,
      view,
      newView,
      sequence,
      proposerId,
      timeoutDurationMs,
      createdAt: now,
      challengerSignature,
    };

    // Store challenge state
    this.registerChallenge(challenge);
    return challenge;
  }

  /**
   * Registers a challenge in internal tracking state.
   */
  public registerChallenge(challenge: ViewChangeTimeoutChallenge): void {
    if (this.usedChallengeIds.has(challenge.challengeId)) {
      return;
    }
    if (this.pendingChallenges.has(challenge.challengeId)) {
      return;
    }

    // Capacity bound check
    if (this.pendingChallenges.size >= this.maxTrackedChallenges) {
      const oldestKey = this.pendingChallenges.keys().next().value;
      if (oldestKey) {
        this.pendingChallenges.delete(oldestKey);
        this.challengeWitnesses.delete(oldestKey);
      }
    }

    this.pendingChallenges.set(challenge.challengeId, challenge);
    if (!this.challengesByView.has(challenge.view)) {
      this.challengesByView.set(challenge.view, new Set());
    }
    this.challengesByView.get(challenge.view)!.add(challenge.challengeId);
  }

  /**
   * Creates a witness proof by signing a challenge timestamp.
   */
  public createWitnessProof(
    challengeId: string,
    witnessNodeId: string,
    signer: BFTSigningInterface,
    timestamp: number = Date.now(),
  ): TimeoutWitnessProof {
    const payload = formatWitnessPayload(challengeId, witnessNodeId, timestamp);
    const signature = signer.sign(payload);
    return {
      witnessNodeId,
      witnessTimestamp: timestamp,
      signature,
    };
  }

  /**
   * Adds a witness proof to a registered challenge.
   */
  public addWitnessProof(
    challengeId: string,
    proof: TimeoutWitnessProof,
    context: TimeoutVerificationContext,
  ): boolean {
    const challenge = this.pendingChallenges.get(challengeId);
    if (!challenge) {
      return false;
    }

    // Verify witness proof before storing
    if (!this.verifyWitnessProof(challengeId, proof, challenge, context)) {
      return false;
    }

    if (!this.challengeWitnesses.has(challengeId)) {
      this.challengeWitnesses.set(challengeId, new Map());
    }

    const witnesses = this.challengeWitnesses.get(challengeId)!;
    // Deduplicate by witnessNodeId
    witnesses.set(proof.witnessNodeId, proof);
    return true;
  }

  /**
   * Gets all witness proofs collected for a challenge.
   */
  public getWitnessProofs(challengeId: string): TimeoutWitnessProof[] {
    const proofs = this.challengeWitnesses.get(challengeId);
    return proofs ? Array.from(proofs.values()) : [];
  }

  /**
   * Assembles complete cryptographic timeout evidence for a challenge.
   */
  public buildTimeoutEvidence(
    challengeId: string,
  ): CryptographicTimeoutEvidence | null {
    const challenge = this.pendingChallenges.get(challengeId);
    if (!challenge) {
      return null;
    }
    const witnesses = this.getWitnessProofs(challengeId);
    return {
      challenge,
      witnesses,
    };
  }

  /**
   * Verifies the cryptographic challenger signature.
   */
  public verifyChallengeSignature(
    challenge: ViewChangeTimeoutChallenge,
    context: TimeoutVerificationContext,
  ): boolean {
    if (!challenge || !challenge.challengerSignature) {
      return false;
    }
    if (!context.validators.includes(challenge.proposerId)) {
      return false;
    }

    const payload = formatChallengePayload({
      challengeId: challenge.challengeId,
      view: challenge.view,
      newView: challenge.newView,
      sequence: challenge.sequence,
      proposerId: challenge.proposerId,
      timeoutDurationMs: challenge.timeoutDurationMs,
      createdAt: challenge.createdAt,
    });

    return this.verifySignature(
      challenge.proposerId,
      payload,
      challenge.challengerSignature,
      context,
    );
  }

  /**
   * Verifies an individual witness proof.
   */
  public verifyWitnessProof(
    challengeId: string,
    proof: TimeoutWitnessProof,
    challenge: ViewChangeTimeoutChallenge,
    context: TimeoutVerificationContext,
  ): boolean {
    if (!proof || !proof.signature || !proof.witnessNodeId) {
      return false;
    }
    if (!context.validators.includes(proof.witnessNodeId)) {
      return false;
    }

    const now = context.now ?? Date.now();
    const tolerance = context.clockToleranceMs ?? this.clockToleranceMs;

    // Witness timestamp must be at or after challenge creation (within clock tolerance)
    if (proof.witnessTimestamp < challenge.createdAt - tolerance) {
      return false;
    }

    // Witness timestamp must not be excessively in the future
    if (proof.witnessTimestamp > now + tolerance) {
      return false;
    }

    // Witness timestamp must reflect that the required timeout duration has elapsed
    // elapsed time = witnessTimestamp - challenge.createdAt
    if (
      proof.witnessTimestamp - challenge.createdAt <
      challenge.timeoutDurationMs - tolerance
    ) {
      return false;
    }

    const payload = formatWitnessPayload(
      challengeId,
      proof.witnessNodeId,
      proof.witnessTimestamp,
    );

    return this.verifySignature(
      proof.witnessNodeId,
      payload,
      proof.signature,
      context,
    );
  }

  /**
   * Independently verifies the complete timeout evidence.
   */
  public verifyTimeoutEvidence(
    evidence: CryptographicTimeoutEvidence,
    context: TimeoutVerificationContext,
  ): boolean {
    try {
      if (!evidence || typeof evidence !== "object") {
        return false;
      }

      const { challenge, witnesses } = evidence;
      if (!challenge || !witnesses || !Array.isArray(witnesses)) {
        return false;
      }

      // 1. Prevent replay of previously accepted or spent challenges
      if (this.usedChallengeIds.has(challenge.challengeId)) {
        return false;
      }

      // 2. Validate consensus context
      // The challenge must target the view change from context.currentView to an authorized next view
      if (challenge.view !== context.currentView) {
        return false;
      }
      if (challenge.newView <= challenge.view) {
        return false;
      }
      if (challenge.sequence < context.currentSequence) {
        return false;
      }

      // 3. Verify timeout duration is at least expectedTimeoutMs
      if (challenge.timeoutDurationMs < context.expectedTimeoutMs) {
        return false;
      }

      const now = context.now ?? Date.now();
      const tolerance = context.clockToleranceMs ?? this.clockToleranceMs;

      // 4. Validate creation timestamp
      if (
        typeof challenge.createdAt !== "number" ||
        isNaN(challenge.createdAt)
      ) {
        return false;
      }
      if (challenge.createdAt > now + tolerance) {
        return false;
      }

      // 5. Verify challenger's cryptographic signature
      if (!this.verifyChallengeSignature(challenge, context)) {
        return false;
      }

      // 6. Verify that the current time has elapsed the required timeout
      if (now - challenge.createdAt < challenge.timeoutDurationMs - tolerance) {
        return false;
      }

      // 7. Verify validator witness signatures and quorum
      const validWitnesses = new Set<string>();

      for (const proof of witnesses) {
        if (!proof || typeof proof !== "object") continue;
        if (validWitnesses.has(proof.witnessNodeId)) continue; // Deduplicate

        if (
          this.verifyWitnessProof(
            challenge.challengeId,
            proof,
            challenge,
            context,
          )
        ) {
          validWitnesses.add(proof.witnessNodeId);
        }
      }

      // Quorum requirement for witnesses
      if (validWitnesses.size < context.quorumSize) {
        return false;
      }

      return true;
    } catch {
      return false;
    }
  }

  /**
   * Marks a challenge as accepted/used to prevent replay attacks.
   */
  public markChallengeUsed(challengeId: string): void {
    this.usedChallengeIds.add(challengeId);
    this.pendingChallenges.delete(challengeId);
    this.challengeWitnesses.delete(challengeId);

    // Bound used challenges size
    if (this.usedChallengeIds.size > this.maxTrackedChallenges * 2) {
      const iter = this.usedChallengeIds.values();
      for (let i = 0; i < this.maxTrackedChallenges; i++) {
        const next = iter.next();
        if (next.done) break;
        this.usedChallengeIds.delete(next.value);
      }
    }
  }

  /**
   * Prunes expired and stale challenges below the current view.
   */
  public pruneStaleChallenges(currentView: number): void {
    for (const [view, challengeSet] of this.challengesByView.entries()) {
      if (view < currentView) {
        for (const cid of challengeSet) {
          this.pendingChallenges.delete(cid);
          this.challengeWitnesses.delete(cid);
        }
        this.challengesByView.delete(view);
      }
    }
  }

  /**
   * Helper to verify a signature against a nodeId.
   */
  private verifySignature(
    nodeId: string,
    payload: Uint8Array,
    signature: string,
    context: TimeoutVerificationContext,
  ): boolean {
    if (context.verifier) {
      return context.verifier.verify(nodeId, payload, signature);
    }

    const keyObj = context.validatorPublicKeys?.get(nodeId);
    if (!keyObj) {
      return false;
    }

    try {
      const sigBuf = Buffer.from(signature, "hex");
      if (sigBuf.length !== 64) {
        return false;
      }
      return verify(null, payload, keyObj, sigBuf);
    } catch {
      return false;
    }
  }
}
